import{_ as a,o as t,c as l,a5 as h}from"./chunks/framework.BPFk9-tb.js";const _=JSON.parse('{"title":"写作课作业-108","description":"","frontmatter":{"date":"2021-02-27T15:25:08","title":"写作课作业-108","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/108.md","filePath":"posts/homework/108.md"}'),o={name:"posts/homework/108.md"};function r(i,e,p,n,s,d){return t(),l("div",null,[...e[0]||(e[0]=[h('<blockquote><p>《区块链小白书》之《比特币 4.比特币解决了什么问题》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>比特币通过分布式管理的方式提过了一个不可篡改的可信账簿。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>传统中心化管理的数据库，用来记账的时候，那账簿是有无数找可以可能被篡改。</p><p>比特币银行自己不管理数据库；把数据库的管理权限交给所有人，大家共同维护账簿；每个人手中的账簿与其他人一样才算是有效账簿；所以全网的所有账都只能一样，没有人可以私自篡改账簿并被其他所有人接受。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><p>先抛出“双花问题”这个比特币的概念，然后对这个概念做解释：“同一笔钱一次只能花在一个地方”。并说银行的核心业务就是记账——不能记错账，更不能做假账。而传统的中心化管理的数据库，用来记账的时候，账簿有无数种可能被篡改，自然而然的引出比特币银行的解决方式。</p><p>而最终需要解决的问题是“必须要有一个不可篡改的可信账簿”，解决方案是“分布式管理”。然后对“去中心化”，“公开透明”的本末倒置的现象做了说明，这些都是分布式管理的结果。</p><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><p>双花问题——同一笔钱一次只能花在一个地方。</p><p>问题是“必须要有一个不可篡改的可信账簿……”，解决方案是“那我们分布式管理罢！”</p><p>“去中心化”并非目标，而是分布式管理的结果，而“公开透明”也只是分布式管理的自然而然的结果……</p><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>之前做医疗的电子病历系统，对病历的修改其实要求挺高的，比如上级修改需要有痕迹，提交后不可以修改，归档的时候还要做数字签名。于是当接触到区块链技术的时候，和一位医疗管理人员聊到的时候，他说除了隐私的问题，医院也不想完全把病历上链变成不可更改的，有时因为各种需要还是希望对一些病历做一些调整。其实非“公开透明”对于一些管理来说，可能也是某种需求。</p><p>自己在看一些比特币的资讯的时候，时常看到的“去中心化”，“公开透明”的特点，如果不是因为看这里说是分布式管理的结果，自己会想到么？很难，能直接联想的的，也就是数据库的“脑裂问题”。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',24)])])}const u=a(o,[["render",r]]);export{_ as __pageData,u as default};
